#include <iostream>
#include <algorithm>
#include <climits>

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

int calculateMaxPathSum(Node* root, int& maxSum) {
    if (root == nullptr) return 0;

    // Calculate left and right subtree contributions (ignoring negative paths)
    int leftSum = std::max(0, calculateMaxPathSum(root->left, maxSum));
    int rightSum = std::max(0, calculateMaxPathSum(root->right, maxSum));

    // Path sum containing root as the highest pivot point
    int currentPathSum = root->data + leftSum + rightSum;

    // Update global maximum
    maxSum = std::max(maxSum, currentPathSum);

    // Return the maximum single-branch path sum to the parent node
    return root->data + std::max(leftSum, rightSum);
}

int maxPathSum(Node* root) {
    int maxSum = INT_MIN;
    calculateMaxPathSum(root, maxSum);
    return maxSum;
}
